                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and out[yy][xx] == 6 and (yy, xx) not in seen:
                        seen.add((yy, xx))
                        stack.append((yy, xx))

            minr = min(y for y, x in comp)
            maxr = max(y for y, x in comp)
            minc = min(x for y, x in comp)
            maxc = max(x for y, x in comp)
            shape = {(y - minr, x - minc) for y, x in comp}
            best = None

            for ar in range(h - (maxr - minr + 1) + 1):
                for ac in range(w - (maxc - minc + 1) + 1):
                    if (ar, ac) == (minr, minc):
