def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    mask = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6}
    seen = set()

    # The hidden areas are copies of other parts of the patterned grid;
    # locate each source patch by matching its visible surroundings, allowing
    # rotations and reflections.
    transforms = [
        lambda y, x: (y, x), lambda y, x: (y, -x),
        lambda y, x: (-y, x), lambda y, x: (-y, -x),
        lambda y, x: (x, y), lambda y, x: (x, -y),
        lambda y, x: (-x, y), lambda y, x: (-x, -y),
    ]

    for start in list(mask):
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        comp = []
        while stack:
            r, c = stack.pop()
            comp.append((r, c))
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                p = (r + dr, c + dc)
                if p in mask and p not in seen:
                    seen.add(p)
                    stack.append(p)

        r0 = min(r for r, c in comp)
        c0 = min(c for r, c in comp)
        r1 = max(r for r, c in comp)
        c1 = max(c for r, c in comp)
        bh, bw = r1 - r0 + 1, c1 - c0 + 1

        best = None
        for orient, fn in enumerate(transforms):
            for ar in range(h):
                for ac in range(w):
                    score = total = 0
                    for dr in range(-7, bh + 7):
                        for dc in range(-7, bw + 7):
                            tr, tc = r0 + dr, c0 + dc
                            if not (0 <= tr < h and 0 <= tc < w) or (tr, tc) in mask:
                                continue
                            sr_off, sc_off = fn(dr, dc)
                            sr, sc = ar + sr_off, ac + sc_off
                            if not (0 <= sr < h and 0 <= sc < w) or grid[sr][sc] == 6:
                                continue
                            weight = 4 if -2 <= dr < bh + 2 and -2 <= dc < bw + 2 else 1
                            total += weight
                            score += weight * (2 if grid[tr][tc] == grid[sr][sc] else -1)
                    if total:
                        key = (score / total, total)
                        if best is None or key > best[0]:
                            best = (key, ar, ac, fn)

        if best:
            _, ar, ac, fn = best
            for r, c in comp:
                dr, dc = r - r0, c - c0
                sr_off, sc_off = fn(dr, dc)
                sr, sc = ar + sr_off, ac + sc_off
                if 0 <= sr < h and 0 <= sc < w and grid[sr][sc] != 6:
                    out[r][c] = grid[sr][sc]

    return out
