    out = [row[:] for row in grid]

    def orbit(r, c):
        points = {(r, c)}
        changed = True
        while changed:
            changed = False
            for y, x in list(points):
                for yy, xx in ((x, y), (31-y, x), (y, 31-x)):
                    if 0 <= yy < h and 0 <= xx < w and (yy, xx) not in points:
                        points.add((yy, xx))
                        changed = True
        return points

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 6:
                for y, x in orbit(r, c):
                    if grid[y][x] != 6:
                        out[r][c] = grid[y][x]
                        break

    return out
